/** Метод для получения списка идентификаторов товаров */
 getProductList(opts?: {
   filter?: Types.GetProductListRequestFilter;
   limit?: number;
 }): Types.Productv2GetProductListResponseItem[] {
   const items: Types.Productv2GetProductListResponseItem[] = [];
   let total = 0;

   const payload: Types.GetProductListRequestInit = {
     limit: opts?.limit || 1000,
     last_id: '',
   };
   if (opts?.filter) {
     payload.filter = opts?.filter;
   }

   do {
     const itemsListResponse = this.request<Types.Productv2GetProductListResponse>({
       endpoint: '/v2/product/list',
       method: 'POST',
       payload,
     });
     // Если количество товаров, соответствующих фильтру, равно 0 - прекращаем цикл
     if (itemsListResponse.result.total == 0) {
       break;
     }
     items.push(...itemsListResponse.result.items);
     total = itemsListResponse.result.total;
     payload.last_id = itemsListResponse.result.last_id;

     /**Итерации будут продолжаться если:
      * в аргументах определен общий лимит И он больше количества загруженных товаров
      * ИЛИ
      * общий лимит не определен И количество загруженных товаров меньше соответствующих фильтру
      */
   } while ((opts?.limit && items.length < opts?.limit) || (!opts?.limit && items.length < total));
   if (opts?.limit && opts?.limit < items.length) {
     return items.splice(0, opts.limit);
   }
   return items;
 }

