  "filter": {
    "visibility": "ALL"
  },
  "limit": 1000
}

count = 0
last = False
while True:
    res = r.post("https://api-seller.ozon.ru/v5/product/info/prices", headers=headers, data = json.dumps(data))
    if res.status_code == 200:
        if last:
            break

        count += 1
        resp_data = res.json()
        print(f"Limit: 1000. Total: {resp_data.get('total')}. Len items: {len(resp_data['items'])} Count: {count}")

        if len(resp_data['items']) == 1000:
            data['cursor'] = resp_data.get('cursor')
        else:
            last = True


    else:
        break

