func check(dateFrom string, dateTo string) bool {
  f := strings.Split(dateFrom, "-")
  t := strings.Split(dateTo, "-")

  fy, _ := strconv.Atoi(f[0])
  fm, _ := strconv.Atoi(f[1])
  fd, _ := strconv.Atoi(f[2])

  td, _ := strconv.Atoi(t[2])

  month := 0
  for i := 1; i <= 12; i++ {
    if fm == i {
      month = i
    }
  }

  days := 0
  for i := 1; i <= 31; i++ {
    if month == 1 || month == 3 || month == 5 || month == 7 || month == 8 || month == 10 || month == 12 {
      days = 31
    } else if month == 4 || month == 6 || month == 9 || month == 11 {
      days = 30
    } else if month == 2 {
      if fy%4 == 0 {
        days = 29
      } else {
        days = 28
      }
    }
  }

  ok := false
  for d := 1; d <= days; d++ {
    if d >= fd {
      if d <= td {
        if d == td {
          ok = true
        }
      }
    }
  }

  return ok
}

